export function lookupAustralianSuburb(name: string, preferredState?: string): SuburbRecord | null {
  if (!name) return null;
  const lower = name.toLowerCase().trim();

  // 1. Try exact 'name:state' match if state provided
  if (preferredState) {
    const key = `${lower}:${preferredState.toLowerCase().trim()}`;
    if (SUBURB_STATE_MAP[key]) {
      const [p, st, title] = SUBURB_STATE_MAP[key].split(":");
      return { suburb: title, postcode: p, state: st, council: detectCouncilForSuburb(title, st, p) };
    }
  }

  // 2. Try by name
  const list = SUBURB_NAMES_MAP[lower];
  if (list && list.length > 0) {
    // If multiple states, prioritize preferredState, or QLD / NSW (Hudson build zones)
    let selected = list[0];
    if (preferredState) {
      const matchPref = list.find((item) => item.split(":")[1] === preferredState.toUpperCase());
      if (matchPref) selected = matchPref;
    } else {
      const matchQldNsw = list.find((item) => item.split(":")[1] === "QLD" || item.split(":")[1] === "NSW");
      if (matchQldNsw) selected = matchQldNsw;
    }
    const [p, st, title] = selected.split(":");
    return { suburb: title, postcode: p, state: st, council: detectCouncilForSuburb(title, st, p) };
  }

  return null;
}

export function lookupSuburbsByPostcode(postcode: string): Array<{ suburb: string; state: string }> {
  if (!postcode) return [];
  const p = postcode.trim();
  const list = POSTCODE_TO_SUBURBS[p] || [];
  return list.map((item) => {
    const [suburb, state] = item.split(":");
    return { suburb, state };
  });
}

export function detectCouncilForSuburb(suburb: string, state: string, postcode: string): string {
  const s = (suburb || "").toLowerCase().trim();
  const p = (postcode || "").trim();

  // Redland City Council ($2,500 / QLD)
  if (
    /mount cotton|mt cotton|capalaba|sheldon|alexandra hills|birkdale|cleveland|victoria point|redland bay|thornlands|wellington point|ormiston|thorneside|burbank/i.test(s) ||
    /^(4165|4157|4161|4163|4164|4159|4160)$/.test(p)
  ) {
    return "Redland City Council";
  }

  // Logan City Council ($2,227 / QLD)
  if (
    /flagstone|greenbank|yarrabilba|jimboomba|new beith|chambers flat|park ridge|logan village|undullah|bahrs scrub|cedar creek|waterford|woodridge|springwood|daisy hill|rochedale south|shailer park|browns plains|boronia heights|crestmead|heritage park|hillcrest|regents park/i.test(s) ||
    /^(4280|4124|4207|4133|4125|4114|4127|4128|4118)$/.test(p)
  ) {
    return "Logan City Council";
  }

  // Ipswich City Council ($2,400 / QLD)
  if (
    /ripley|south ripley|springfield|spring mountain|redbank plains|deebing heights|bellbird park|brookwater|camira|collingwood park|goodna|raceview|brassall|booval|yamanto|flinders view/i.test(s) ||
    /^(4306|4300|4301|4305|4304)$/.test(p)
  ) {
    return "Ipswich City Council";
  }

  // City of Gold Coast ($2,850 / QLD)
  if (
    /coomera|upper coomera|pimpama|ormeau|helensvale|hope island|pacific pines|oxenford|gaven|nerang|robina|varsity lakes|southport|surfers paradise/i.test(s) ||
    /^(4209|4208|4212|4210|4211|4226|4217|4215)$/.test(p)
  ) {
    return "City of Gold Coast";
  }

  // City of Moreton Bay ($2,350 / QLD)
  if (
    /north harbour|burpengary|morayfield|caboolture|narangba|mango hill|north lakes|kallangur|deception bay|griffin|murrumba downs|petrie|strathpine/i.test(s) ||
    /^(4505|4506|4510|4504|4509|4503|4500)$/.test(p)
  ) {
    return "City of Moreton Bay";
  }

  // Sunshine Coast Council ($2,450 / QLD)
  if (
    /palmview|harmony|pelican waters|caloundra|baringa|nirimba|maroochydore|buderim|sippy downs|kawana|coolum|mooloolaba/i.test(s) ||
    /^(4553|4551|4558|4556|4575|4573|4557)$/.test(p)
  ) {
    return "Sunshine Coast Council";
  }

  // Brisbane City Council ($3,190 / QLD)
  if (
    /rochedale|bridgeman downs|pallara|heathwood|graceville|sherwood|chelmer|indooroopilly|toowong|chermside|carindale|wynnum|manly|kenmore|calamvale|sunnybank|algester/i.test(s) ||
    (state === "QLD" && /^(4000|4005|4006|4064|4068|4075|4101|4102|4109|4110|4113|4115|4116|4122|4123|4152|4178|4179|4032|4034|4053|4069)$/.test(p))
  ) {
    return "Brisbane City Council";
  }

  // Blacktown City Council ($2,000 / NSW)
  if (
    /blacktown|marsden park|schofields|riverstone|tallawong|colebee|stanhope gardens|the ponds|glenwood|kellyville ridge|mount druitt|rooty hill|quakers hill/i.test(s) ||
    /^(2148|2765|2762|2761|2768|2763|2767|2769|2770)$/.test(p)
  ) {
    return "Blacktown City Council";
  }

  // The Hills Shire Council ($2,000 / NSW)
  if (
    /box hill|the gables|gables|castle hill|baulkham hills|bella vista|norwest|kellyville|north kellyville|beaumont hills|rouse hill|kenthurst|dural/i.test(s) ||
    /^(2154|2153|2155|2156|2158)$/.test(p)
  ) {
    return "The Hills Shire";
  }

  // Camden Council ($2,000 / NSW)
  if (
    /camden|oran park|gregory hills|leppington|gledswood hills|catherine field|harrington park|spring farm|mount annan|elderslie|narellan|cobbitty/i.test(s) ||
    /^(2570|2567|2557)$/.test(p)
  ) {
    return "Camden Council";
  }

  // Campbelltown City Council ($2,000 / NSW)
  if (
    /campbelltown|menangle park|macarthur|glenfield|ingleburn|minto|leumeah|raby|rosemeadow/i.test(s) ||
    /^(2560|2564|2565|2566)$/.test(p)
  ) {
    return "Campbelltown City Council";
  }

  // Liverpool City Council ($2,000 / NSW)
  if (
    /liverpool|austral|edmondson park|moorebank|casula|prestons|warwick farm|chipping norton|hoxton park|carnes hill|hinchinbrook/i.test(s) ||
    /^(2170|2179|2174|2171|2168)$/.test(p)
  ) {
    return "Liverpool City Council";
  }

  // City of Parramatta ($2,000 / NSW)
  if (
    /parramatta|westmead|northmead|harris park|rosehill|rydalmere|ermington|dundas|carlingford|epping/i.test(s) ||
    /^(2150|2145|2116|2117|2118|2121)$/.test(p)
  ) {
    return "City of Parramatta";
  }

  // Penrith City Council ($2,000 / NSW)
  if (
    /penrith|jordan springs|glenmore park|mulgoa|orchard hills|st marys|kingswood|cranebrook|emu plains/i.test(s) ||
    /^(2750|2745|2747|2748|2749|2752)$/.test(p)
  ) {
    return "Penrith City Council";
  }

  // Wollondilly Shire Council ($2,000 / NSW)
  if (
    /wilton|appin|tahmoor|picton|bargo|thirlmere|silverdale|the oaks|warragamba/i.test(s) ||
    /^(2571|2560|2573|2574|2752)$/.test(p)
  ) {
    return "Wollondilly Shire Council";
  }

  // Shellharbour & Wollongong ($2,000 / NSW)
  if (/calderwood|albion park|shellharbour|wollongong|dapto|bulli|corrimal|figtree/i.test(s)) {
    return /calderwood|albion park|shellharbour/i.test(s) ? "Shellharbour City Council" : "Wollongong City Council";
  }

  // Hunter & Central Coast ($2,000 / NSW)
  if (/newcastle|lake macquarie|maitland|cessnock|gosford|wyong|central coast|lochinvar|huntlee|rothbury/i.test(s)) {
    if (/maitland|lochinvar/i.test(s)) return "Maitland City Council";
    if (/cessnock|huntlee|rothbury/i.test(s)) return "Cessnock City Council";
    if (/lake macquarie/i.test(s)) return "Lake Macquarie City Council";
    if (/newcastle/i.test(s)) return "City of Newcastle";
    return "Central Coast Council";
  }

  return "";
}

/**
 * Searches Australian Suburbs index directly (fast prefix & token matching).
 */
export function searchAustralianSuburbs(query: string, limit = 10, stateFilter?: string): SuburbRecord[] {
  if (!query || query.trim().length < 2) return [];
  const q = query.toLowerCase().trim();
  const results: SuburbRecord[] = [];
  const seen = new Set<string>();

  // 1. Check known estates first
  for (const est of KNOWN_ESTATES) {
    if (est.keywords.some((k) => k.includes(q) || q.includes(k))) {
      if (stateFilter && est.state.toUpperCase() !== stateFilter.toUpperCase()) continue;
      const key = `${est.suburb.toLowerCase()}_${est.postcode}`;
      if (!seen.has(key)) {
        seen.add(key);
        results.push({
          suburb: est.suburb,
          postcode: est.postcode,
          state: est.state,
          council: est.council,
        });
      }
    }
  }

  // 2. Exact or prefix matches on suburb names
  for (const [lowerName, list] of Object.entries(SUBURB_NAMES_MAP)) {
    if (lowerName.startsWith(q) || lowerName.includes(q)) {
      for (const entry of list) {
        const [p, st, title] = entry.split(":");
        if (stateFilter && st.toUpperCase() !== stateFilter.toUpperCase()) continue;
        const key = `${title.toLowerCase()}_${p}`;
        if (!seen.has(key)) {
          seen.add(key);
          results.push({
            suburb: title,
            postcode: p,
            state: st,
            council: detectCouncilForSuburb(title, st, p),
          });
        }
      }
    }
    if (results.length >= limit * 2) break;
  }

  // Sort prefix matches first
  results.sort((a, b) => {
    const aStarts = a.suburb.toLowerCase().startsWith(q) ? -1 : 0;
    const bStarts = b.suburb.toLowerCase().startsWith(q) ? -1 : 0;
    return aStarts - bStarts;
  });

  return results.slice(0, limit);
}
